.version 8.0
.target sm_89
.address_size 64
.shared .align 4 .b8 sA[32]; // 8 floats for blockDim.y=8
.visible .entry matmul_tall_skinny_f32(
    .param .u64 A_ptr,
    .param .u64 B_ptr,
    .param .u64 C_ptr,
    .param .u32 M,
    .param .u32 K,
    .param .u32 N
)
{
    .reg .pred p0, p1, p2, pRow, pCol, pValid;
    .reg .b32 rM, rK, rN, ri, rj, rk;
    .reg .b32 rtid_x, rtid_y, rctaid_x, rctaid_y, rntid_x, rntid_y;
    .reg .b64 rA, rB, rC, addrA, addrB, addrC, idx64, tmp64a, tmp64b, rk64, rj64, sAbase, sArow;
    .reg .f32 fa, fb, facc, sa;
    // Load parameters
    ld.param.u64 rA, [A_ptr];
    ld.param.u64 rB, [B_ptr];
    ld.param.u64 rC, [C_ptr];
    ld.param.u32 rM, [M];
    ld.param.u32 rK, [K];
    ld.param.u32 rN, [N];
    // Compute thread coordinates: i (row), j (col)
    mov.u32 rtid_x, %tid.x;
    mov.u32 rtid_y, %tid.y;
    mov.u32 rctaid_x, %ctaid.x;
    mov.u32 rctaid_y, %ctaid.y;
    mov.u32 rntid_x, %ntid.x;
    mov.u32 rntid_y, %ntid.y;
    mad.lo.s32 rj, rctaid_x, rntid_x, rtid_x; // j = blockIdx.x * blockDim.x + threadIdx.x
    mad.lo.s32 ri, rctaid_y, rntid_y, rtid_y; // i = blockIdx.y * blockDim.y + threadIdx.y
    cvt.u64.u32 rj64, rj;
    // Predicates for bounds
    setp.lt.u32 pRow, ri, rM;
    setp.lt.u32 pCol, rj, rN;
    and.pred    pValid, pRow, pCol;
    // Accumulator init
    mov.f32 facc, 0f00000000;
    // Setup shared memory base and per-row pointer
    mov.u64 sAbase, sA;
    mul.wide.u32 sArow, rtid_y, 4;        // offset = ty * 4
    add.u64      sArow, sAbase, sArow;    // address for this row in smem
    mov.u32 rk, 0;
LOOP_K:
    setp.ge.u32 p1, rk, rK;
    @p1 bra STORE;
    // Load A[i,k] once per row (threadIdx.x == 0), broadcast via shared memory
    setp.eq.u32 p2, rtid_x, 0;
    @!p2 bra SKIP_LOAD_A;
        @pRow bra LOAD_A;
        // Row out of bounds: write zero into shared memory
        mov.f32 fa, 0f00000000;
        st.shared.f32 [sArow], fa;
        bra AFTER_LOAD_A;
LOAD_A:
        cvt.u64.u32 rk64, rk;
        mad.wide.u32 tmp64a, ri, rK, rk64;   // i*K + rk in 64-bit
        shl.b64      tmp64a, tmp64a, 2;      // *4 bytes
        add.u64      addrA,  rA,     tmp64a;
        ld.global.f32 fa, [addrA];
        st.shared.f32 [sArow], fa;
AFTER_LOAD_A:
SKIP_LOAD_A:
    // Ensure A row value is visible to all threads
    bar.sync 0;
    // Only threads with valid column index load B and participate
    @!pCol bra SKIP_FMA;
        // addrB = B + ((rk*N + j) * 4)
        mad.wide.u32 tmp64b, rk, rN, rj64;   // rk*N + j in 64-bit
        shl.b64      tmp64b, tmp64b, 2;      // *4 bytes
        add.u64      addrB,  rB,     tmp64b;
        ld.global.f32 fb, [addrB];
        ld.shared.f32 sa, [sArow];
        @pRow fma.rn.f32   facc, sa, fb, facc;
SKIP_FMA:
    add.s32 rk, rk, 1;
    bra LOOP_K;
STORE:
    // Store C only for valid threads
    @!pValid bra DONE;
    // addrC = C + ((i*N + j) * 4)
    mad.wide.u32 idx64,  ri, rN, rj64;   // i*N + j in 64-bit
    shl.b64      idx64,  idx64,  2;    // *4 bytes
    add.u64      addrC,  rC,     idx64;
    st.global.f32 [addrC], facc;
DONE:
    ret;
